topics_out = []
for t in a12["topics"]:
    tid = t["topic_id"]
    cp = []
    for c in t["concepts"]:
        cid = c["concept_id"]
        for i, b in enumerate(c["content"]):
            if b["type"] != "paragraph":
                continue
            key = (cid, i)
            assert key in CP, "missing concept paragraph %s" % (key,)
            cp.append({"concept_id": cid, "content_index": i,
                       "publication_text": CP[key]})
    pub_text = PT[tid]
    pub_chunk = chunks[tid] + "\n\n" + pub_text + "\n\n" + AN[tid]
    topics_out.append({"topic_id": tid,
                       "publication_text": pub_text,
                       "publication_chunk": pub_chunk,
                       "concept_publication": cp})

out = {"agent": "16_publication_authoring",
       "chapter_id": w5["chapter_id"],
       "plan_id": w5["plan_id"],
       "grade": w5["grade"],
       "topics": topics_out,
       "notes": [
         "publication_text is each topic's teaching `explanation` with the vocative (‘બાળકો, જુઓ —’) and the direct classroom instruction (‘પકડી લો’, ‘ધ્યાનથી જુઓ’, ‘એમ ન સમજતાં’) removed. Every fact, every inline gloss and every reading is carried across unchanged; nothing was added, and the length band is unchanged.",
         "publication_chunk = the verbatim `original_chunk` from 05_with_content.json, copied byte-for-byte and never reflowed, followed by the topic's publication_text and then the topic's `real_life_example` rendered for a reader (second person and the closing question dropped, the same single picture kept). No sentence in a chunk states anything the teaching block did not already state.",
         "concept_publication carries one entry per `paragraph` block of Agent 12's concepts[].content[], in order, with content_index as it stands in that array (list blocks keep their indices and are simply not emitted, so indices run 0 and 2 in the three-block concepts). 25 paragraph blocks across 15 concepts; none renumbered, reordered or dropped.",
         "std 7, ધોરણ tier, ગદ્ય વાર્તા: no verse is involved, so no કડી/ટેક/છાપ line was at risk. The chapter's one quoted title line (‘‘ચક્રવ્યૂહ તૂટ્યો પણ આપણો ભડવીર ખૂટ્યો !’’) appears only as printed, inside the verbatim chunk and quoted as-is in prose.",
         "No અલંકાર, છંદ or સાહિત્યપ્રકાર label appears anywhere — the std-7 naming ceiling that Agent 12 held is held here too. No numbers in display text; no Roman or Devanagari outside the Gujarati script; `.` throughout, never `।`."
       ]}

with io.open(os.path.join(OUT, "16_publication.json"), "w", encoding="utf-8") as f:
    json.dump(out, f, ensure_ascii=False, indent=2)
    f.write("\n")

print("topics:", len(topics_out), "concept_publication entries:",
      sum(len(x["concept_publication"]) for x in topics_out))
